extends Node3D

@export var frequency: float = 1.0
@export var amplitude: float = 1.5
@export var speed: float = 2.0  # how fast t advances
@export var max_points: int = 200

var time: float = 0.0
var points: Array[Vector3] = []

func _process(delta: float) -> void:
	time += delta
	# x advances with time
	var x = time * speed
	# y is the wave: amplitude × sin(frequency × time)
	var y = amplitude * sin(frequency * time)
	var new_point = Vector3(x, y, 0)
	points.append(new_point)
	if points.size() > max_points:
		points.pop_front()

func _setup_visuals() -> void:
	trail_mesh = ImmediateMesh.new()
	trail_instance.mesh = trail_mesh
	var material = StandardMaterial3D.new()
	material.albedo_color = Color(0.2, 1.0, 0.5)  # Green trail
	material.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	trail_instance.material_override = material

func _redraw_trail() -> void:
	trail_mesh.clear_surfaces()
	if points.size() < 2:
		return
	trail_mesh.surface_begin(Mesh.PRIMITIVE_LINE_STRIP)
	for p in points:
		trail_mesh.surface_add_vertex(p)
	trail_mesh.surface_end()

@export var frequency: float = 1.0
@export var amplitude: float = 1.5

func apply_grid_config(config: Dictionary) -> void:
	if config.has("frequency"):
		frequency = float(config["frequency"])
	if config.has("amplitude"):
		amplitude = float(config["amplitude"])
	if config.has("speed"):
		speed = float(config["speed"])

func _on_freq_slider(pos: float) -> void:
	frequency = remap(pos, 0.0, 1.0, 0.25, 4.0)
